package com.example.notitia.bridge

// The Rust core as the shared code sees it. On Android, Kotlin generated by UniFFI holds it; on the iPhone, a Swift
// class does. Swift cannot suspend, emit a Flow or throw one of our exceptions: every function here blocks, takes
// and returns plain values, and reports a failure as a value. A meeting, a request and an event cross as JSON text
// (ADR 0004), so a new one changes neither of the two classes that hold this interface. Only the sound and the key
// of the app cross as bytes.
interface NotitiaCore {
    // Reads the meetings of the folder and tells them to the listener before it returns. null once open. The key of
    // the app, 32 bytes, crosses here only: without one the meetings open, but nothing is recorded.
    fun open(directory: String, key: ByteArray?, listener: CoreListener): CoreFailure?

    // The whole meeting, lines included.
    fun meeting(id: String): CoreReply

    // null when the core read the request: what it changed, and a file it could not write, come as events.
    fun apply(request: String): CoreFailure?

    // The microphone's sound, 16-bit little-endian at 16 kHz, from the microphone's own thread: returns at once and
    // never throws, so a read is never late.
    fun hear(track: Int, pcm: ByteArray)

    // The sound of a meeting in the same shape, ready to play: a minute at most per call.
    fun sound(id: String, fromMs: Long, lengthMs: Long): CoreSound

    // Every engine this app can run now, in JSON, in place of those offered before (core/src/engine/lent.rs): the
    // core tells which it chose as an event. Invalid for an offer it would have to correct. Both holders hand the core
    // the engines through neverThrowing.
    fun offer(offered: String, engines: CoreEngines): CoreFailure?
}

// Runs an engine of this app for the core, on a thread of the core: it blocks until the engine is done. The request
// and the reply are JSON, the sound 16-bit little-endian at 16 kHz. A failure is a reply.
fun interface CoreEngines {
    fun run(engine: String, request: String, sound: ByteArray): String
}

internal const val ENGINE_FAILED = """{"type":"failed"}"""

// An engine that throws, a gateway out of reach say, answers that it failed: UniFFI would turn the exception into a
// panic of the core, and on the iPhone it would end the app on its way through Swift. A function, not an extension,
// so Swift calls it as plainly as Kotlin.
fun neverThrowing(engines: CoreEngines): CoreEngines = CoreEngines { engine, request, sound ->
    try {
        engines.run(engine, request, sound)
    } catch (_: Exception) {
        ENGINE_FAILED
    }
}

// The key of the app, as the core takes it (core/src/secret.rs).
internal const val KEY_BYTES = 32

// Called by the core on the thread that asked for a change, before its file is written, or on a thread of its own,
// the recorder's or the pipeline's. It must not ask the core for anything, which would wait for itself, and it must
// not throw: nothing on the way back catches.
fun interface CoreListener {
    fun onEvent(event: String)
}

// One of the two is null. Classes of their own rather than a generic one: Swift builds them, without a compiler
// here to check how.
class CoreReply(val text: String?, val failure: CoreFailure?)

class CoreSound(val pcm: ByteArray?, val failure: CoreFailure?)

// Invalid is a text the core does not read as a request, Broken a fault of the core itself or of its bridge: both
// are ours, never the user's.
enum class CoreFailure { NotFound, Unreadable, Invalid, Broken }
